function twoEggDrop(n) {
  const dp = new Array(n + 1).fill(0);

  for (let floors = 1; floors <= n; floors++) {
    dp[floors] = floors;
    for (let x = 1; x <= floors; x++) {
      const worst = Math.max(x, 1 + dp[floors - x]);
      dp[floors] = Math.min(dp[floors], worst);
    }
  }
  return dp[n];
}

