function twoEggDrop(n) {
  // With m moves and two eggs you can cover at most m + (m - 1) + ... + 1 floors.
  let moves = 0;
  let covered = 0;
  while (covered < n) {
    moves++;
    covered += moves;
  }
  return moves;
}

